package com.abhiai.abhiai_backend.service;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import com.abhiai.abhiai_backend.dto.moderation.ModerationActionRequest;import com.abhiai.abhiai_backend.entity.*;import com.abhiai.abhiai_backend.exception.*;import com.abhiai.abhiai_backend.repository.*;
@Service public class ModerationService{private final PostRepository posts;private final UserRepository users;private final ContentReportRepository reports;private final ModerationAuditLogRepository audits;private final Set<String> admins;public ModerationService(PostRepository p,UserRepository u,ContentReportRepository r,ModerationAuditLogRepository a,@Value("${abhiai.admin.emails:}")String configured){posts=p;users=u;reports=r;audits=a;admins=new HashSet<>(Arrays.stream(configured.split(",")).map(x->x.trim().toLowerCase()).filter(x->!x.isBlank()).toList());}
 @Transactional public void execute(String email,ModerationActionRequest r){if(!admins.contains(email.toLowerCase()))throw new UnauthorizedActionException("Administrator access is required");switch(r.action()){case"REMOVE_POST"->posts.findById(r.targetId()).orElseThrow(PostNotFoundException::new).softDelete();case"RESTORE_POST"->posts.findById(r.targetId()).orElseThrow(PostNotFoundException::new).restore();case"VERIFY_USER"->users.findById(r.targetId()).orElseThrow(UserNotFoundException::new).changeVerifiedStatus(parseVerification(r.value()));case"REVIEW_REPORT"->reports.findById(r.targetId()).orElseThrow(()->new UnauthorizedActionException("Report not found")).review(parseReport(r.value()));default->throw new UnauthorizedActionException("Unsupported moderation action");}audits.save(new ModerationAuditLog(email,r.action(),r.targetType(),r.targetId(),r.reason().trim()));}
 private VerifiedStatus parseVerification(String v){try{return VerifiedStatus.valueOf(v);}catch(Exception e){throw new UnauthorizedActionException("Invalid verification status");}}private ReportStatus parseReport(String v){try{return ReportStatus.valueOf(v);}catch(Exception e){throw new UnauthorizedActionException("Invalid report status");}}
}
